frame.store("_a_persons_eye", { let __signature_189 = Signature { name: "_a_persons_eye".into(), positional: vec!["understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_191 = Value::dict(); __attrs_191.dict_set(Value::from("__doc__"), Value::from("False when the eye belongs to an animal, so the pet card answers it.\n\n    Whose the eye is has to be read from the sentence and not from the line's subject: the subject\n    of \"my horse has something in his eye\" is the eye itself, so the subject alone sent it back to\n    this row. What tells the two apart is the possessive - \"his eye\" on a line that names an animal\n    is the animal's - and a line that keeps the eye for the person (\"my dog scratched my eye\",\n    \"the dog poked me in the eye\") stays here, because the animal is the cause and not the patient.\n    "))?; __attrs_191.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_192 = Value::dict(); __attrs_191.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_188 = Frame::module(frame.globals.clone()); let mut __function_190 = NativeFunction::qualified_with_origin("_a_persons_eye".into(), "_a_persons_eye".into(), "bot.knowledge.health".into(), __attrs_191, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/health.py", first: 297, last: 311, qualname: "_a_persons_eye" }, closure: __closure_188.clone(), freevars: vec![] }, move |rt, args| __py_9::_a_persons_eye(rt, __closure_188.clone(), &__signature_189, args)); __function_190 })?;
frame.store("_the_eye_is_said", { let __signature_194 = Signature { name: "_the_eye_is_said".into(), positional: vec!["understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_196 = Value::dict(); __attrs_196.dict_set(Value::from("__doc__"), Value::from("False when the line has no eye in it, so the tear film cannot answer a line about water.\n\n    \"watering\" is a key here because \"my eyes are ALWAYS watering\" had no phrase to match, and\n    the same word is what a vase, a bath, a garden and a glass of water are about: the fold\n    reaches this row from \"water\" alone, so \"what is the freezing point of water\" and \"i cant\n    keep water down\" were answered with the tear film. The subject the row is about has to be\n    in the line: an eye, eyes, an eyelid or lashes. Used as an entry `guard`, so it reads the\n    same reading every row does.\n    "))?; __attrs_196.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_197 = Value::dict(); __attrs_196.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_193 = Frame::module(frame.globals.clone()); let mut __function_195 = NativeFunction::qualified_with_origin("_the_eye_is_said".into(), "_the_eye_is_said".into(), "bot.knowledge.health".into(), __attrs_196, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/health.py", first: 314, last: 326, qualname: "_the_eye_is_said" }, closure: __closure_193.clone(), freevars: vec![] }, move |rt, args| __py_10::_the_eye_is_said(rt, __closure_193.clone(), &__signature_194, args)); __function_195 })?;
