frame.store("_medicine_when_pregnant_or_feeding", { let __signature_204 = Signature { name: "_medicine_when_pregnant_or_feeding".into(), positional: vec!["memory".into(),"reading".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_206 = Value::dict(); __attrs_206.dict_set(Value::from("__doc__"), Value::from("The pregnancy answer, unless the line is about feeding - then it is not this entry's.\n\n    \"can i take paracetamol while breastfeeding\" was answered by this row because it is the\n    higher one, and the first sentence talks about pregnancy to someone who is feeding. The\n    feeding answer already exists one entry down; this row only has to stop at the lines that\n    are not about pregnancy.\n    "))?; __attrs_206.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_207 = Value::dict(); __attrs_206.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_203 = Frame::module(frame.globals.clone()); let mut __function_205 = NativeFunction::qualified_with_origin("_medicine_when_pregnant_or_feeding".into(), "_medicine_when_pregnant_or_feeding".into(), "bot.knowledge.health".into(), __attrs_206, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/health.py", first: 345, last: 358, qualname: "_medicine_when_pregnant_or_feeding" }, closure: __closure_203.clone(), freevars: vec![] }, move |rt, args| __py_12::_medicine_when_pregnant_or_feeding(rt, __closure_203.clone(), &__signature_204, args)); __function_205 })?;
