let __v_7241 = pyrt::literals::decode("{\"$tuple\":[\"eye test\",\"eye exam\",\"sight test\",\"mot\",\"mot test\",\"driving test\",\"theory test\",\"test drive\",\"exam\",\"exams\",\"gcse\",\"a level\",\"a-level\",\"school\",\"college\",\"university\",\"interview\",\"job\",\"coursework\",\"assignment\",\"iq test\",\"pcr\",\"swab test kit\",\"covid test\",\"results day\",\"results are out\",\"grades\",\"pregnancy test\",\"pregnancy tests\",\"lateral flow\"]}")?;
